import java.util.stream.IntStream;

public class binarytrees {

    private static final int MIN_DEPTH = 4;

    static final class Node {
        Node left, right;

        Node(Node l, Node r) {
            left = l;
            right = r;
        }

        int check() {
            int c = 1;
            Node n = this;
            while (n.left != null) {
                c += n.right.check() + 1;
                n = n.left;
            }
            return c;
        }
    }

    static Node bottomUp(int depth) {
        if (depth <= 0) return new Node(null, null);
        depth--;
        return new Node(bottomUp(depth), bottomUp(depth));
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0].trim());
        int maxDepth = Math.max(MIN_DEPTH + 2, n);
        int stretchDepth = maxDepth + 1;

        StringBuilder sb = new StringBuilder();

        int stretchCheck = bottomUp(stretchDepth).check();
        sb.append("stretch tree of depth ").append(stretchDepth)
          .append("\t check: ").append(stretchCheck).append('\n');

        Node longLived = bottomUp(maxDepth);

        for (int d = MIN_DEPTH; d <= maxDepth; d += 2) {
            final int depth = d;
            int iterations = 1 << (maxDepth - depth + MIN_DEPTH);
            long check = IntStream.range(0, iterations)
                    .parallel()
                    .mapToLong(i -> bottomUp(depth).check())
                    .sum();
            sb.append(iterations).append("\t trees of depth ").append(depth)
              .append("\t check: ").append(check).append('\n');
        }

        sb.append("long lived tree of depth ").append(maxDepth)
          .append("\t check: ").append(longLived.check()).append('\n');

        System.out.print(sb);
        System.out.flush();
    }
}
