public class pidigits {
    private static final BigInteger TEN = BigInteger.valueOf(10);
    private static final BigInteger THREE = BigInteger.valueOf(3);
    private static final BigInteger FOUR = BigInteger.valueOf(4);

    private static BigInteger num = BigInteger.ONE;
    private static BigInteger acc = BigInteger.ZERO;
    private static BigInteger den = BigInteger.ONE;

    private static void nextTerm(int k) {
        BigInteger y2 = BigInteger.valueOf(2L * k + 1);
        acc = acc.add(num.shiftLeft(1));
        acc = acc.multiply(y2);
        den = den.multiply(y2);
        num = num.multiply(BigInteger.valueOf(k));
    }

    private static int extractDigit(BigInteger nth) {
        BigInteger tmp = num.multiply(nth).add(acc);
        return tmp.divide(den).intValue();
    }

    private static void eliminateDigit(int d) {
        acc = acc.subtract(den.multiply(BigInteger.valueOf(d)));
        acc = acc.multiply(TEN);
        num = num.multiply(TEN);
    }

    public static void main(String[] args) {
        int n = Integer.parseInt(args[0]);
