            multiplyAtAv(u, tmp, v);
            multiplyAtAv(v, tmp, u);
        }

        double vBv = 0.0, vv = 0.0;
        for (int i = 0; i < n; i++) {
            vBv += u[i] * v[i];
            vv += v[i] * v[i];
        }

        System.out.printf("%.9f%n", Math.sqrt(vBv / vv));
    }
}
